// === Tab: Beings ===
// ====================== Wesen ======================

class FlatlandBeing {
  constructor(x, y, type, r, col) {
    this.pos = createVector(x, y);
    this.vel = p5.Vector.random2D().mult(random(1, 4));
    this.type = type;
    this.radius = r;
    this.col = col;
    this.mode = "normal";   // "normal" | "frozen"
    this.freezeTimer = 0;
    this.facingRight = random([true, false]);
  }

  move() {
    this.pos.add(this.vel);

    // Wände der Ebene
    if (this.pos.x < this.radius) {
      this.pos.x = this.radius;
      this.vel.x *= -1;
    }
    if (this.pos.x > width - this.radius) {
      this.pos.x = width - this.radius;
      this.vel.x *= -1;
    }
    if (this.pos.y < this.radius) {
      this.pos.y = this.radius;
      this.vel.y *= -1;
    }
    if (this.pos.y > height - this.radius) {
      this.pos.y = height - this.radius;
      this.vel.y *= -1;
    }

    this.vel.limit(2.5);
  }

  avoidOverlap(others) {
    for (let o of others) {
      if (o === this) continue;
      const d = dist(this.pos.x, this.pos.y, o.pos.x, o.pos.y);
      const minD = this.radius + o.radius;      // statt this.radius * 2
      if (d > 0 && d < minD) {
        const pushDir = p5.Vector.sub(this.pos, o.pos).setMag((minD - d) * 0.05);
        this.pos.add(pushDir);
        this.vel.add(p5.Vector.mult(pushDir, 0.5));
      }
    }
    this.vel.limit(2.5);
  }


  show() {
    // Füllung
    noStroke();
    fill(this.col);
    this.drawShape(this.pos.x, this.pos.y, this.type, this.radius);

    // Kontur minimal darüber zeichnen
    push();
    translate(0, 0, 0.1);  // 0.1 Einheiten über der Füllung → kein Z-Fighting
    stroke(0);
    strokeWeight(2);
    noFill();
    this.drawShape(this.pos.x, this.pos.y, this.type, this.radius);
    pop();


    // „Seitenansicht“-Gesicht
    this.drawSideFace(this.pos.x, this.pos.y);
  }

  drawShape(x, y, type, r) {
    if (type === "circle") {
      ellipse(x, y, r * 2);
    } else {
      let sides = 3;
      if (type === "square") sides = 4;
      if (type === "hexagon") sides = 6;

      beginShape();
      for (let i = 0; i < sides; i++) {
        let angle = (360 / sides) * i - 90;
        let vx = x + r * cos(angle);
        let vy = y + r * sin(angle);
        vertex(vx, vy);
      }
      endShape(CLOSE);
    }
  }

  drawSideFace(x, y) {
  if (this.facingRight) {
    fill(0);
    noStroke();
    ellipse(x + 18, y - 10, 6, 6);
    noFill();
    stroke(0);
    strokeWeight(2);
    line(x + 10, y + 10, x + 20, y + 10);
  } else {
    fill(0);
    noStroke();
    ellipse(x - 18, y - 10, 6, 6);
    noFill();
    stroke(0);
    strokeWeight(2);
    line(x - 10, y + 10, x - 20, y + 10);
  }
}

}

