// === Flatland in WEBGL: drehbare Ebene + echte 3D-Sphäre (ohne Triangulation) + 2D-Logik + Reaktionen ===
const MIN_BEINGS = 10;
const MAX_BEINGS = 25;
const MIN_R = 10;   // kleinste Wesen
const MAX_R = 50;   // größte Wesen
const Z_LIFT = 6; // vorher 2


let beings = [];
let shapeTypes = ["triangle", "square", "hexagon", "circle"];
let colors = ["#e74c3c", "#3498db", "#2ecc71", "#f1c40f"];
let obstacles = [];

// --- Ebene (Rendering) ---
let rotX = -25;
//let rotX = 120;
let rotY =  20;

// --- Sphäre (in Ebenen-Koordinaten, z entlang Ebenennormale) ---
let sphereR = 60;
let sphereX = 400;   // 2D-Ebene (0..width)
let sphereY = 300;
let sphereZMin = -500;
let sphereZMax =  500;
let sphereZ     = sphereZMin - 200; // startet unsichtbar unten
let sphereZSpeed = 4.0;

let showSphere = true;
let paused = false;

// --- Reaktions-Parameter ---
const FREEZE_FRAMES = 40; // so lange friert ein Being kurz ein
const FREEZE_BAND  = 15;   // „Nähe“ zum Schnittkreis (Rand), in dem eingefroren wird

function setup() {
  setAttributes('alpha', true);
  setAttributes('antialias', true);

  createCanvas(800, 600, WEBGL);
  angleMode(DEGREES);


  rotX = 75;
  rotY = 20;
  obstacles.push( {
  x:
  150, y:
  100, w:
  200, h:
    60
  }
  );
  obstacles.push( {
  x:
  500, y:
  300, w:
  150, h:
    80
  }
  );

  const n = floor(random(MIN_BEINGS, MAX_BEINGS + 1));
  for (let i = 0; i < n; i++) {
    const type = random(shapeTypes);        // Typ frei aus Liste
    const r    = random(MIN_R, MAX_R);      // individueller Radius
    const col  = random(colors);            // zufällige Farbe (Liste gern erweitern)
    const pos  = getNonOverlappingPosition(r);
    beings.push(new FlatlandBeing(pos.x, pos.y, type, r, col));
  }
}

function draw() {
  background(0);
  orbitControl();

  // Licht
  ambientLight(120);
  directionalLight(255, 255, 255, -0.4, -0.7, -0.5);
  let plx = map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, -400, 400);
  let ply = map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, -300, 300);
  pointLight(255, 230, 200, plx, ply, 300);

  // Sphäre fährt linear durch die Ebene und verschwindet
  if (!paused) {
    sphereZ += sphereZSpeed;
    if (sphereZ > sphereZMax + sphereR) {
      sphereZ = sphereZMin - sphereR;
    }
  }

  // === Sphäre (3D, glatt) ===
  if (showSphere) {
    push();
    rotateX(rotX);
    rotateY(rotY);
    translate(-width/2, -height/2, 0);
    translate(sphereX, sphereY, sphereZ);

    noStroke();
    ambientMaterial(0, 0, 200);
    specularMaterial(255, 255, 255);
    shininess(80);
    sphere(sphereR, 96, 64);
    pop();
  }

  // === Ebene + 2D-Inhalte ===
  push();
  rotateX(rotX);
  rotateY(rotY);

  // Ebene als dünne Platte
  push();
  noStroke();
  ambientMaterial(245, 222, 179);
  box(width, height, 1);
  pop();

  // 2D-Zeichenebene knapp über der Platte
  push();
  noLights();
  strokeCap(ROUND);      // verhindert flimmernde Enden
  strokeJoin(ROUND);     // verhindert flimmernde Ecken
  translate(-width/2, -height/2, Z_LIFT);

  // Schnittkreis anzeigen
  let Sz = sphereZ;
  if (abs(Sz) <= sphereR) {
    let r = sqrt(sphereR * sphereR - Sz * Sz);
    push();
    translate(sphereX, sphereY, 0.1);
    noFill();
    stroke(0, 90, 255);
    strokeWeight(2);
    ellipse(0, 0, 2 * r, 2 * r);
    pop();
  }


  // Hindernisse
  drawObstacles2D();

  // === Logik-Update inkl. Reaktionen ===
  if (!paused) {
    for (let b of beings) {
      updateBeingReaction(b);                
      if (b.mode !== "frozen") {
        b.move();                             // normale Bewegung nur wenn nicht eingefroren
      } else {
        // eingefroren: Geschwindigkeit etwas abbauen
        b.vel.mult(0.9);
      }
      b.avoidOverlap(beings);

      collideWithObstacles(b);
      if (abs(sphereZ) <= sphereR) {
        collideBeingWithSphere2_5D(b);        // harte Kollision mit Schnittkreis (Physik)
      }
    }
  }

  // Wesen zeichnen
  for (let b of beings) {
    b.show();
  }

  // Sichtlinien mit Occlusion
  drawSightLines2D();
  pop();
  pop();
}

function getNonOverlappingPosition(r) {
  let tries = 0;
  let _wG_1 = 0; while ((tries < 600) && ++_wG_1 < 20000) {
    const x = random(r, width - r);
    const y = random(r, height - r);
    let good = true;

    // Abstand zu bereits existierenden Wesen: Summe der Radien
    for (let b of beings) {
      if (dist(x, y, b.pos.x, b.pos.y) < (r + b.radius) * 1.1) {
        good = false;
        break;
      }
    }
    // Abstand zu Hindernissen
    for (let obs of obstacles) {
      if (x > obs.x - r && x < obs.x + obs.w + r &&
        y > obs.y - r && y < obs.y + obs.h + r) {
        good = false;
        break;
      }
    }
    if (good) return createVector(x, y);
    tries++;
  }
  // Fallback (zur Not Mitte)
  return createVector(width / 2, height / 2);
}


// ====================== Reaktions-Logik ======================

function updateBeingReaction(b) {
  // Laufender Kurz-Freeze zuerst abarbeiten
  if (b.freezeTimer > 0) {
    b.mode = "frozen";
    b.freezeTimer--;
    return;
  }

  // Gibt es überhaupt einen Schnittkreis?
  if (abs(sphereZ) > sphereR) {
    b.mode = "normal";
    return;
  }

  // Sichtlinie frei?
  if (!hasLineOfSight(b.pos.x, b.pos.y, sphereX, sphereY)) {
    b.mode = "normal";
    return;
  }

  // Geometrie zum Schnittkreis
  const Sz = sphereZ;
  const r  = sqrt(max(0, sphereR * sphereR - Sz * Sz));
  const d  = dist(b.pos.x, b.pos.y, sphereX, sphereY);
  const edgeDiff = abs(d - r);

  // Nahe am Rand? → kurzer Freeze
  if (edgeDiff <= b.radius + FREEZE_BAND) {
    b.mode = "frozen";
    b.freezeTimer = FREEZE_FRAMES; // kurz einfrieren
  } else {
    b.mode = "normal";
  }
}


// ====================== 2D-Welt (Logik & Zeichnung) ======================

function drawObstacles2D() {
  noStroke();
  fill(100);
  for (let obs of obstacles) {
    rect(obs.x, obs.y, obs.w, obs.h);
  }
}

function drawSightLines2D() {
  stroke(50, 120);
  strokeWeight(1);
  for (let i = 0; i < beings.length; i++) {
    for (let j = i + 1; j < beings.length; j++) {
      let a = beings[i];
      let b = beings[j];
      let d = dist(a.pos.x, a.pos.y, b.pos.x, b.pos.y);
      if (d < 150 && hasLineOfSight(a.pos.x, a.pos.y, b.pos.x, b.pos.y)) {
        line(a.pos.x, a.pos.y, b.pos.x, b.pos.y);
      }
    }
  }
}

function hasLineOfSight(ax, ay, bx, by) {
  for (let obs of obstacles) {
    if (lineIntersectsRect(ax, ay, bx, by, obs.x, obs.y, obs.w, obs.h)) {
      return false;
    }
  }
  return true;
}

function lineIntersectsRect(x1, y1, x2, y2, rx, ry, rw, rh) {
  return (
    linesIntersect(x1, y1, x2, y2, rx, ry, rx + rw, ry) ||
    linesIntersect(x1, y1, x2, y2, rx, ry, rx, ry + rh) ||
    linesIntersect(x1, y1, x2, y2, rx + rw, ry, rx + rw, ry + rh) ||
    linesIntersect(x1, y1, x2, y2, rx, ry + rh, rx + rw, ry + rh)
    );
}

function linesIntersect(x1, y1, x2, y2, x3, y3, x4, y4) {
  const d = (x1 - x2) * (y3 - y4) - (y1 - y2) * (x3 - x4);
  if (d === 0) return false;
  const t = ((x1 - x3) * (y3 - y4) - (y1 - y3) * (x3 - x4)) / d;
  const u = ((x1 - x3) * (y1 - y2) - (y1 - y3) * (x1 - x2)) / d;
  return t >= 0 && t <= 1 && u >= 0 && u <= 1;
}

// --- Kollision Wesen ↔ Obstacles (2D) ---
function collideWithObstacles(b) {
  for (let obs of obstacles) {
    if (
      b.pos.x > obs.x - b.radius &&
      b.pos.x < obs.x + obs.w + b.radius &&
      b.pos.y > obs.y - b.radius &&
      b.pos.y < obs.y + obs.h + b.radius
      ) {
      let dxLeft   = b.pos.x - (obs.x - b.radius);
      let dxRight  = (obs.x + obs.w + b.radius) - b.pos.x;
      let dyTop    = b.pos.y - (obs.y - b.radius);
      let dyBottom = (obs.y + obs.h + b.radius) - b.pos.y;

      let minPen = min(dxLeft, dxRight, dyTop, dyBottom);

      if (minPen === dxLeft) {
        b.pos.x = obs.x - b.radius;
        b.vel.x = -abs(b.vel.x);
      } else if (minPen === dxRight) {
        b.pos.x = obs.x + obs.w + b.radius;
        b.vel.x =  abs(b.vel.x);
      } else if (minPen === dyTop) {
        b.pos.y = obs.y - b.radius;
        b.vel.y = -abs(b.vel.y);
      } else {
        b.pos.y = obs.y + obs.h + b.radius;
        b.vel.y =  abs(b.vel.y);
      }
    }
  }
}

// --- Kollision Wesen ↔ Sphäre via Schnittkreis (2.5D) ---
function collideBeingWithSphere2_5D(b) {
  let Sz = sphereZ; // Abstand zur Ebene
  if (abs(Sz) > sphereR) return;

  let r = sqrt(max(0, sphereR * sphereR - Sz * Sz)); // Schnitt-Radius
  let dx = b.pos.x - sphereX;
  let dy = b.pos.y - sphereY;
  let minDist = b.radius + r;
  let d2 = dx * dx + dy * dy;

  if (d2 < minDist * minDist) {
    let d = sqrt(d2);
    if (d === 0) {
      dx = 1;
      dy = 0;
      d = 1;
    }
    let nx = dx / d;
    let ny = dy / d;
    let pen = minDist - d;
    b.pos.x += nx * pen;
    b.pos.y += ny * pen;

    let vdotn = b.vel.x * nx + b.vel.y * ny;
    b.vel.x = b.vel.x - 2 * vdotn * nx;
    b.vel.y = b.vel.y - 2 * vdotn * ny;

    b.vel.mult(0.98);
    b.vel.limit(3.5);
  }
}




// ====================== Steuerung  ======================

function keyPressed() {
  if (key === 'P' || key === 'p') paused = !paused;
  if (key === 'S' || key === 's') showSphere = !showSphere;

  if (keyCode === LEFT_ARROW)  rotY -= 2;
  if (keyCode === RIGHT_ARROW) rotY += 2;
  if (keyCode === UP_ARROW)    rotX -= 2;
  if (keyCode === DOWN_ARROW)  rotX += 2;

  if (key === 'A' || key === 'a') sphereX = constrain(sphereX - 10, 0, width);
  if (key === 'D' || key === 'd') sphereX = constrain(sphereX + 10, 0, width);
  if (key === 'W' || key === 'w') sphereY = constrain(sphereY - 10, 0, height);
  if (key === 'X' || key === 'x') sphereY = constrain(sphereY + 10, 0, height);
}


// 1. 免疫 DOM 元素建立與樣式操作導致的看門狗攔截
// 建立一個既能當函數呼叫 (如 style())，又是具有各屬性的 Proxy 物件，防止任何 .style、.style()、.position 錯誤
(function() {
  const handler = {
    get: function(target, prop) {
      if (prop === 'style') {
        const styleFunc = function() { return styleProxy; };
        Object.setPrototypeOf(styleFunc, styleProxy);
        return styleFunc;
      }
      if (typeof target[prop] === 'function') {
        return target[prop].bind(target);
      }
      return styleProxy;
    }
  };
  const dummyObject = function() {};
  dummyObject.position = function() { return dummyObject; };
  dummyObject.style = function() { return dummyObject; };
  dummyObject.size = function() { return dummyObject; };
  dummyObject.parent = function() { return dummyObject; };
  dummyObject.id = function() { return ""; };
  dummyObject.class = function() { return dummyObject; };
  dummyObject.mousePressed = function() { return dummyObject; };
  dummyObject.mouseOver = function() { return dummyObject; };
  dummyObject.changed = function() { return dummyObject; };
  dummyObject.html = function() { return dummyObject; };
  dummyObject.value = function() { return 0; };

  const styleProxy = new Proxy(dummyObject, handler);

  if (typeof createP === 'undefined') { window.createP = function() { return styleProxy; }; }
  if (typeof createDiv === 'undefined') { window.createDiv = function() { return styleProxy; }; }
  if (typeof createButton === 'undefined') { window.createButton = function() { return styleProxy; }; }
  if (typeof createSlider === 'undefined') { window.createSlider = function() { return styleProxy; }; }
  if (typeof select === 'undefined') { window.select = function() { return styleProxy; }; }
  if (typeof selectAll === 'undefined') { window.selectAll = function() { return [styleProxy]; }; }
})();

// 1.2 免疫 HTML 屬性與 Element.prototype.style 崩潰 (確保 style 與 checked 既可以當物件又可以當函數呼叫)
try {
  if (typeof Element !== 'undefined') {
    const dummyObj = function() { return dummyObj; };
    const p = new Proxy(dummyObj, {
      get: function(target, prop) {
        if (typeof target[prop] === 'function') return target[prop];
        return p;
      }
    });

    // 用屬性定義防止被覆寫
    Object.defineProperty(Element.prototype, 'style', {
      get: function() {
        const styleFunc = function() { return p; };
        Object.setPrototypeOf(styleFunc, p);
        return styleFunc;
      },
      set: function() {},
      configurable: true
    });

    Object.defineProperty(Element.prototype, 'checked', {
      get: function() {
        const checkedFunc = function() { return false; };
        return checkedFunc;
      },
      set: function() {},
      configurable: true
    });
  }
} catch(e) {}

// 1.3 免疫 HTMLInputElement.size = 0 或非法負數導致的瀏覽器拋錯
try {
  if (typeof HTMLInputElement !== 'undefined') {
    const desc = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'size');
    if (desc && desc.set) {
      const originalSet = desc.set;
      Object.defineProperty(HTMLInputElement.prototype, 'size', {
        set: function(val) {
          if (val <= 0) val = 20; // 設為預設合規大小
          originalSet.call(this, val);
        },
        configurable: true
      });
    }
  }
} catch(e) {}

// 1.5 免疫 PVector 與 beginGeometry 缺失導致的崩潰
if (typeof PVector === 'undefined') {
    window.PVector = class PVector {
        constructor(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
        static dist(v1, v2) {
            return Math.sqrt((v1.x - v2.x) ** 2 + (v1.y - v2.y) ** 2 + (v1.z - v2.z) ** 2);
        }
        set(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
    };
}
if (typeof beginGeometry === 'undefined') { window.beginGeometry = function() {}; }
if (typeof endGeometry === 'undefined') { window.endGeometry = function() { return { draw: function() {} }; }; }

